use actix_web::{web, App, HttpServer, HttpResponse, Responder, Error};
use serde::{Deserialize, Serialize};
use rusqlite::{params, Connection, Result};
use std::env;
use std::sync::Mutex;

#[derive(Serialize, Deserialize)]
struct Product {
    name: String,
    #[serde(flatten)]
    properties: std::collections::HashMap<String, String>,
}

#[derive(Serialize, Deserialize)]
struct ProductData {
    name: String,
    data: String,
}

#[derive(Serialize, Deserialize)]
struct SearchResult {
    results: Vec<Product>,
}

struct AppState {
    db: Mutex<Connection>,
}

async fn add_product(data: web::Json<Product>, state: web::Data<AppState>) -> impl Responder {
    let conn = state.db.lock().unwrap();
    let product_json = serde_json::to_string(&data.into_inner()).unwrap();

    match conn.execute(
        "INSERT INTO products (name, data) VALUES (?1, ?2)",
        params![data.name, product_json],
    ) {
        Ok(_) => HttpResponse::Created().finish(),
        Err(_) => HttpResponse::BadRequest().finish(),
    }
}

async fn download_product(web::Query(info): web::Query<std::collections::HashMap<String, String>>, state: web::Data<AppState>) -> impl Responder {
    let conn = state.db.lock().unwrap();
    let name = info.get("name").unwrap();

    let mut stmt = conn.prepare("SELECT data FROM products WHERE name = ?1").unwrap();
    let product_iter = stmt.query_map(params![name], |row| row.get(0)).unwrap();

    for product in product_iter {
        return HttpResponse::Ok().json(ProductData {
            name: name.clone(),
            data: product.unwrap(),
        });
    }

    HttpResponse::BadRequest().finish()
}

async fn upload_product(data: web::Json<ProductData>, state: web::Data<AppState>) -> impl Responder {
    let conn = state.db.lock().unwrap();

    match conn.execute(
        "UPDATE products SET data = ?1 WHERE name = ?2",
        params![data.data, data.name],
    ) {
        Ok(_) => HttpResponse::Ok().finish(),
        Err(_) => HttpResponse::BadRequest().finish(),
    }
}

async fn search_products(web::Query(info): web::Query<std::collections::HashMap<String, String>>, state: web::Data<AppState>) -> impl Responder {
    let conn = state.db.lock().unwrap();
    let query = info.get("query").unwrap();

    let mut stmt = conn.prepare("SELECT data FROM products WHERE data LIKE ?1").unwrap();
    let product_iter = stmt.query_map(params![format!("%{}%", query)], |row| row.get(0)).unwrap();

    let mut results = Vec::new();
    for product in product_iter {
        let product_data: String = product.unwrap();
        let product: Product = serde_json::from_str(&product_data).unwrap();
        results.push(product);
    }

    HttpResponse::Ok().json(SearchResult { results })
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    let database_url = "db.sqlite3";
    let conn = Connection::open(database_url).unwrap();

    conn.execute(
        "CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL UNIQUE,
            data TEXT NOT NULL
        )",
        [],
    ).unwrap();

    let app_state = web::Data::new(AppState {
        db: Mutex::new(conn),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(app_state.clone())
            .route("/add", web::post().to(add_product))
            .route("/download", web::get().to(download_product))
            .route("/upload", web::post().to(upload_product))
            .route("/search", web::get().to(search_products))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}
